+  editing: WorkspaceView | null;
+  onClose(): void;
+  /** "Use an existing folder…": the folder-picker flow, for Google Drive or OneDrive folders. */
+  onUseExisting(): void;
+  onCreated(result: Created): void;
+  onSaved(result: Saved): void;
+}
+
