+  if (deps.registry.readOnly) return { ok: false, reason: "read-only" };
+  if (!deps.registry.get(id)) return { ok: false, reason: "unknown" };
+  const busy = deps.busy();
+  return busy ? { ok: false, reason: busy } : null;
